function CommentsSheet({palette,comments,comment,setComment,replyTo,setReplyTo,close,addComment,reactComment}:{palette:any;comments:any;comment:string;setComment:(value:string)=>void;replyTo:Comment|null;setReplyTo:(value:Comment|null)=>void;close:()=>void;addComment:any;reactComment:any}){return <KeyboardAvoidingView style={st.commentOverlay} behavior={Platform.OS==='ios'?'padding':undefined}><Pressable accessibilityRole="button" accessibilityLabel="Close comments" onPress={close} style={st.commentBackdrop}/><View style={[st.commentSheet,{backgroundColor:palette.surface}]}><View style={st.sheetHandle}/><View style={st.commentSheetHeader}><Text style={[st.commentSheetTitle,{color:palette.text}]}>All comments</Text><Ionicons name="chevron-down" size={18} color={palette.text}/><View style={{flex:1}}/><Pressable accessibilityRole="button" accessibilityLabel="Close comments" onPress={close} style={st.touch}><Ionicons name="close" size={23} color={palette.text}/></Pressable></View><ScrollView style={st.commentList} contentContainerStyle={{paddingHorizontal:16,paddingBottom:18}} keyboardShouldPersistTaps="handled">{comments.isLoading?<Muted>Loading comments…</Muted>:comments.data?.length===0?<Muted style={{textAlign:'center',paddingVertical:28}}>No comments yet. Start the conversation.</Muted>:comments.data?.map((c:Comment)=><View key={c.Id} style={[st.comment,c.ParentCommentId&&{marginLeft:34}]}><Avatar name={`${c.FirstName} ${c.LastName}`} uri={c.ProfileImage} size={38}/><View style={{flex:1}}><View style={st.commentNameRow}><Text style={[st.commentAuthor,{color:palette.text}]}>{c.FirstName} {c.LastName}</Text><Muted> · {new Date(c.CreatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</Muted></View><LinkText style={[st.commentBody,{color:palette.text}]}>{c.Body}</LinkText><Pressable accessibilityRole="button" accessibilityLabel={`Reply to ${c.FirstName}`} onPress={()=>setReplyTo(c)}><Muted style={st.replyLabel}>Reply</Muted></Pressable></View><View style={st.commentVotes}><Pressable accessibilityRole="button" accessibilityLabel="Like comment" onPress={()=>reactComment.mutate({item:c,reaction:'LIKE'})} style={st.commentVote}><Ionicons name={c.MyReaction==='LIKE'?'thumbs-up':'thumbs-up-outline'} size={18} color={c.MyReaction==='LIKE'?palette.primary:palette.muted}/><Muted>{c.LikeCount||''}</Muted></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Dislike comment" onPress={()=>reactComment.mutate({item:c,reaction:'DISLIKE'})} style={st.commentVote}><Ionicons name={c.MyReaction==='DISLIKE'?'thumbs-down':'thumbs-down-outline'} size={18} color={c.MyReaction==='DISLIKE'?palette.primary:palette.muted}/><Muted>{c.DislikeCount||''}</Muted></Pressable></View></View>)}</ScrollView>{replyTo?<View style={[st.replying,{backgroundColor:palette.primarySoft}]}><Text style={{color:palette.text,flex:1}}>Replying to {replyTo.FirstName}</Text><Pressable onPress={()=>setReplyTo(null)}><Ionicons name="close" size={18} color={palette.text}/></Pressable></View>:null}<View style={[st.commentComposer,{borderTopColor:palette.border}]}><TextInput value={comment} onChangeText={setComment} placeholder="Add a comment…" placeholderTextColor={palette.muted} returnKeyType="send" onSubmitEditing={()=>comment.trim()&&!addComment.isPending&&addComment.mutate()} style={[st.commentInput,{color:palette.text,borderColor:palette.border}]}/><Pressable accessibilityRole="button" accessibilityLabel={replyTo?'Send reply':'Send comment'} disabled={!comment.trim()||addComment.isPending} onPress={()=>addComment.mutate()} style={[st.commentSend,{backgroundColor:comment.trim()?palette.primary:palette.border}]}><Ionicons name="send" size={19} color="#fff"/></Pressable></View></View></KeyboardAvoidingView>}
function Quick({icon,label,color,onPress}:{icon:keyof typeof Ionicons.glyphMap;label:string;color:string;onPress:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={`Add ${label}`} onPress={onPress} style={st.quick}><Ionicons name={icon} size={24} color={color}/><Text numberOfLines={1} style={st.quickText}>{label}</Text></Pressable>}
