function IssueQueue({items,loading,canManage,palette,update,preview}:{items:any[];loading:boolean;canManage:boolean;palette:any;update:(id:string,status:string)=>void;preview:(attachment:Attachment)=>void}){if(loading)return <Muted>Loading confidential reports…</Muted>;return <View><View style={[st.reportHero,{backgroundColor:palette.primarySoft}]}><Ionicons name="shield-checkmark-outline" size={42} color={palette.primary}/><View style={{flex:1}}><Text style={[st.reportHeading,{color:palette.primaryDark}]}>{canManage?'Community report queue':'Your submitted reports'}</Text><Muted>{canManage?'Review confidential member reports and record the action taken.':'Track the confidential issues you have submitted to the community team.'}</Muted></View></View>{items.length?items.map(i=><Card key={i.Id}><View style={st.reportTop}><Badge text={String(i.Status).replace('_',' ')} tone={i.Status==='RESOLVED'?'green':i.Status==='IN_PROGRESS'?'orange':'blue'}/><Muted>{new Date(i.CreatedAt).toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}</Muted></View><Text style={[st.reportHeading,{color:palette.text}]}>{i.Category}</Text>{canManage?<Muted>Submitted by {i.FirstName} {i.LastName}{i.ApproximateLocation?` · ${i.ApproximateLocation}`:''}</Muted>:i.ApproximateLocation?<Muted>{i.ApproximateLocation}</Muted>:null}<Text style={[st.reportBody,{color:palette.text}]}>{i.Description}</Text>{i.PhotoUrl?<Pressable accessibilityRole="button" accessibilityLabel="Preview report evidence" onPress={()=>preview({url:i.PhotoUrl,title:`${i.Category} evidence`})} style={st.smallAction}><Ionicons name="attach-outline" size={20} color={palette.primary}/><Text style={{color:palette.primary,fontWeight:'800'}}>Open evidence</Text></Pressable>:null}{i.ResolutionNote?<Muted>Resolution: {i.ResolutionNote}</Muted>:null}{canManage&&i.Status!=='RESOLVED'?<View style={st.reportActions}><Button title="Assign" variant="secondary" onPress={()=>update(i.Id,'ASSIGNED')}/><Button title="Investigate" variant="secondary" onPress={()=>update(i.Id,'IN_PROGRESS')}/><Button title="Resolve" variant="success" onPress={()=>update(i.Id,'RESOLVED')}/></View>:null}</Card>):<EmptyState icon="shield-checkmark-outline" title="No submitted reports" body={canManage?'New member reports will appear here for authorised administrators to action.':'Use the + button to submit a confidential community issue.'}/>}</View>}
